# Surah Fussilat (chapter 41) — part 2: ayat 13-24 (IDs 4231-4242)
SURAH = 41

ENTRIES = {
4231: (
"پس اگر وہ منہ موڑیں تو کہہ دیجیے میں تمہیں ایک چمک (صاعقہ) سے ڈراتا ہوں جو عاد و ثمود والی چمک کی طرح ہے",
"""۱۔ تنبیہ — إن أعرضوا؛ أنذرتكم صاعقةً؛ كصاعقة عاد و ثمود۔
۲۔ ’’فَإِنْ أَعْرَضُوا فَقُلْ أَنذَرْتُكُمْ صَاعِقَۃً مِّثْلَ صَاعِقَۃِ عَادٍ وَثَمُودَ‘‘ —پس اگر وہ منہ موڑیں تو کہہ دیجیے میں تمہیں ایک چمک (صاعقہ) سے ڈراتا ہوں جو عاد و ثمود والی چمک کی طرح ہے۔
۳۔ عملی سبق: منہ نہ موڑو؛ گزشتہ قوموں کے انجام سے عبرت لو؛ اللہ سے ڈرو۔"""
),
4232: (
"جب ان کے پاس رسول سامنے سے اور پیچھے سے آئے کہ اللہ کے سوا کسی کی عبادت نہ کرو — تو انہوں نے کہا اگر ہمارا رب چاہتا تو فرشتے اتار دیتا — پس ہم اس چیز کا انکار کرتے ہیں جس کے ساتھ تم بھیجے گئے ہو",
"""۱۔ مطالعۂ گزشتہ — الرسل من بين أيديهم و من خلفهم؛ لو شاء ربنا لأنزل ملائكةً؛ كافرون۔
۲۔ ’’إِذْ جَاءَتْهُمُ الرُّسُلُ مِن بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ أَلَّا تَعْبُدُوا إِلَّا اللَّهَ قَالُوا لَوْ شَاءَ رَبُّنَا لَأَنزَلَ مَلَائِكَۃً فَإِنَّا بِمَا أُرْسِلْتُم بِهِ كَافِرُونَ‘‘ — جب ان کے پاس رسول سامنے سے اور پیچھے سے آئے کہ اللہ کے سوا کسی کی عبادت نہ کرو — تو انہوں نے کہا اگر ہمارا رب چاہتا تو فرشتے اتار دیتا — پس ہم اس چیز کا انکار کرتے ہیں جس کے ساتھ تم بھیجے گئے ہو — یعنی جب ان کے پاس رسول سامنے سے اور پیچھے سے آئے کہ اللہ کے سوا کسی کی عبادت نہ کرو تو انہوں نے کہا اگر ہمارا رب چاہتا تو فرشتے اتار دیتا پس ہم اس چیز کا انکار کرتے ہیں جس کے ساتھ تم بھیجے گئے ہو۔
۳۔ عملی سبق: رسولوں کی بات مانو؛ بہانے نہ بناؤ؛ اللہ سے ڈرو۔"""
),
4233: (
"پھر عاد والوں نے زمین میں ناحق تکبر کیا اور کہا ہم سے زیادہ طاقتور کون ہے — کیا انہوں نے نہیں دیکھا کہ اللہ جس نے انہیں پیدا کیا وہ ان سے زیادہ طاقتور ہے — اور وہ ہماری آیات کا انکار کرتے تھے",
"""۱۔ عاد کا تکبر — استكبروا في الأرض بغير الحق؛ من أشد منا قوۃً؛ اللہ أشد منهم قوۃً؛ يجحدون۔
۲۔ ’’فَأَمَّا عَادٌ فَاسْتَكْبَرُوا فِي الْأَرْضِ بِغَيْرِ الْحَقِّ وَقَالُوا مَنْ أَشَدُّ مِنَّا قُوَّۃً أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَهُمْ هُوَ أَشَدُّ مِنْهُمْ قُوَّۃً وَكَانُوا بِآيَاتِنَا يَجْحَدُونَ‘‘ — پھر عاد والوں نے زمین میں ناحق تکبر کیا اور کہا ہم سے زیادہ طاقتور کون ہے — کیا انہوں نے نہیں دیکھا کہ اللہ جس نے انہیں پیدا کیا وہ ان سے زیادہ طاقتور ہے — اور وہ ہماری آیات کا انکار کرتے تھے — یعنی پھر عاد والوں نے زمین میں ناحق تکبر کیا اور کہا ہم سے زیادہ طاقتور کون ہے کیا انہوں نے نہیں دیکھا کہ اللہ جس نے انہیں پیدا کیا وہ ان سے زیادہ طاقتور ہے اور وہ ہماری آیات کا انکار کرتے تھے۔
۳۔ عملی سبق: طاقت پر مغرور نہ ہو؛ اللہ کی قدرت کو پہچانو؛ اللہ سے ڈرو۔"""
),
4234: (
"پس ہم نے ان پر منحوس دنوں میں ایک کڑکڑانے والی ہوا بھیج دی تاکہ انہیں دنیاوی زندگی میں ذلت کا عذاب چکھائیں — اور بے شک آخرت کا عذاب زیادہ ذلیل کرنے والا ہے — اور انہیں مدد نہیں دی جائے گی",
"""۱۔ عذابِ عاد — ریح صرصر؛ أيام نحسات؛ عذاب الخزي؛ عذاب الآخرۃ أخزی؛ لا ینصرون۔
۲۔ ’’فَأَرْسَلْنَا عَلَيْهِمْ رِيحًا صَرْصَرًا فِي أَيَّامٍ نَّحِسَاتٍ لِّنُذِيقَهُمْ عَذَابَ الْخِزْيِ فِي الْحَيَاۃِ الدُّنْيَا وَلَعَذَابُ الْآخِرَۃِ أَخْزَىٰ وَهُمْ لَا يُنصَرُونَ‘‘ — پس ہم نے ان پر منحوس دنوں میں ایک کڑکڑانے والی ہوا بھیج دی تاکہ انہیں دنیاوی زندگی میں ذلت کا عذاب چکھائیں — اور بے شک آخرت کا عذاب زیادہ ذلیل کرنے والا ہے — اور انہیں مدد نہیں دی جائے گی — یعنی پس ہم نے ان پر منحوس دنوں میں ایک کڑکڑانے والی ہوا بھیج دی تاکہ انہیں دنیاوی زندگی میں ذلت کا عذاب چکھائیں اور بے شک آخرت کا عذاب زیادہ ذلیل کرنے والا ہے اور انہیں مدد نہیں دی جائے گی۔
۳۔ عملی سبق: تکبر چھوڑو؛ اللہ کے عذاب سے ڈروسے بچو؛ خوفِ خدا اختیار کرو۔"""
),
4235: (
"اور ثمود والوں کو ہم نے ہدایت دی — پھر انہوں نے ہدایت پر اندھے پن کو ترجیح دی — پس انہیں رسوا کرنے والا ہلاک کرنے والا عذاب آ پکڑا اس عمل کی وجہ سے جو وہ کماتے تھے",
"""۱۔ ثمود کا انجام — هدیناهم؛ فاستحبوا العمی علی الہدی؛ صاعقۃ العذاب الهون؛ بما کانوا يكسبون۔
۲۔ ’’وَأَمَّا ثَمُودُ فَهَدَيْنَاهُمْ فَاسْتَحَبُّوا الْعَمَىٰ عَلَى الْهُدَىٰ فَأَخَذَتْهُمْ صَاعِقَۃُ الْعَذَابِ الْهُونِ بِمَا كَانُوا يَكْسِبُونَ‘‘ — اور ثمود والوں کو ہم نے ہدایت دی — پھر انہوں نے ہدایت پر اندھے پن کو ترجیح دی — پس انہیں رسوا کرنے والا ہلاک کرنے والا عذاب آ پکڑا اس عمل کی وجہ سے جو وہ کماتے تھے — یعنی اور ثمود والوں کو ہم نے ہدایت دی پھر انہوں نے ہدایت پر اندھے پن کو ترجیح دی پس انہیں رسوا کرنے والا ہلاک کرنے والا عذاب آ پکڑا اس عمل کی وجہ سے جو وہ کماتے تھے۔
۳۔ عملی سبق: ہدایت پر اندھے پن کو ترجیح نہ دو؛ اللہ سے ڈرو۔"""
),
4236: (
"اور ہم نے ان لوگوں کو نجات دی جو ایمان لائے اور تقویٰ اختیار کرتے تھے",
"""۱۔ نجاتِ متقین — نجینا الذین آمنوا؛ کانوا یتقون۔
۲۔ ’’وَنَجَّيْنَا الَّذِينَ آمَنُوا وَكَانُوا يَتَّقُونَ‘‘ —اور ہم نے ان لوگوں کو نجات دی جو ایمان لائے اور تقویٰ اختیار کرتے تھے۔
۳۔ عملی سبق: ایمان اور تقویٰ اختیار کرو؛ اللہ سے ڈرو۔"""
),
4237: (
"اور جس دن اللہ کے دشمنوں کو آگ کی طرف اکٹھا کیا جائے گا وہ روکے جائیں گے",
"""۱۔ حشرِ کفار — یوم یحشر أعداء اللہ إلی النار؛ فهم یوزعون۔
۲۔ ’’وَيَوْمَ يُحْشَرُ أَعْدَاءُ اللَّهِ إِلَى النَّارِ فَهُمْ يُوزَعُونَ‘‘ —اور جس دن اللہ کے دشمنوں کو آگ کی طرف اکٹھا کیا جائے گا وہ روکے جائیں گے۔
۳۔ عملی سبق: اللہ کے دشمن نہ بنو؛ اللہ سے ڈرو۔"""
),
4238: (
"یہاں تک کہ جب وہ اس کے پاس پہنچیں گے ان کے کان ان کی آنکھیں اور ان کی کھالیں ان پر اس کے خلاف گواہی دیں گی جو وہ کرتے تھے",
"""۱۔ اعضا کی گواہی — شهد علیهم سمعهم و أبصارهم و جلودهم؛ بما کانوا یعملون۔
۲۔ ’’حَتَّىٰ إِذَا مَا جَاءُوهَا شَهِدَ عَلَيْهِمْ سَمْعُهُمْ وَأَبْصَارُهُمْ وَجُلُودُهُم بِمَا كَانُوا يَعْمَلُونَ‘‘ —یہاں تک کہ جب وہ اس کے پاس پہنچیں گے ان کے کان ان کی آنکھیں اور ان کی کھالیں ان پر اس کے خلاف گواہی دیں گی جو وہ کرتے تھے۔
۳۔ عملی سبق: ہر عضو کو گناہ سے بچاؤ؛ اللہ سے ڈرو۔"""
),
4239: (
"اور وہ اپنی کھالوں سے کہیں گے تم نے ہمارے خلاف گواہی کیوں دی — وہ کہیں گی اللہ نے ہمیں بولنے کی طاقت دی ہے جس نے ہر چیز کو گویائی دی — اور اسی نے تمہیں پہلی بار پیدا کیا — اور اسی کی طرف تم لوٹائے جاؤ گے",
"""۱۔ کھالوں کا جواب — لما شهدتم علینا؛ أنطقنا اللہ الذی أنطق کل شیء؛ خلقکم أول مرة؛ إلیه ترجعون۔
۲۔ ’’وَقَالُوا لِجُلُودِهِمْ لِمَ شَهِدتُّمْ عَلَيْنَا قَالُوا أَنطَقَنَا اللَّهُ الَّذِي أَنطَقَ كُلَّ شَيْءٍ وَهُوَ خَلَقَكُمْ أَوَّلَ مَرَّۃٍ وَإِلَيْهِ تُرْجَعُونَ‘‘ — اور وہ اپنی کھالوں سے کہیں گے تم نے ہمارے خلاف گواہی کیوں دی — وہ کہیں گی اللہ نے ہمیں بولنے کی طاقت دی ہے جس نے ہر چیز کو گویائی دی — اور اسی نے تمہیں پہلی بار پیدا کیا — اور اسی کی طرف تم لوٹائے جاؤ گے — یعنی اور وہ اپنی کھالوں سے کہیں گے تم نے ہمارے خلاف گواہی کیوں دی وہ کہیں گی اللہ نے ہمیں بولنے کی طاقت دی ہے جس نے ہر چیز کو گویائی دی اور اسی نے تمہیں پہلی بار پیدا کیا اور اسی کی طرف تم لوٹائے جاؤ گے۔
۳۔ عملی سبق: اپنی طبیعت کو صحیح استعمال کرو؛ اللہ سے ڈرو۔"""
),
4240: (
"اور تم اس بات سے چھپتے نہ تھے کہ تمہارے کان تمہاری آنکھیں اور تمہاری کھالیں تم پر گواہی دیں گی — بلکہ تم نے سمجھا کہ اللہ تمہارے اکثر اعمال نہیں جانتا",
"""۱۔ غلط فہمی — ما كنتم تستترون أن يشهد علیكم سمعكم و لا أبصاركم و لا جلودكم؛ ظننتم أن اللہ لا یعلم کثیراً مما تعملون۔
۲۔ ’’وَمَا كُنتُمْ تَسْتَتِرُونَ أَن يَشْهَدَ عَلَيْكُمْ سَمْعُكُمْ وَلَا أَبْصَارُكُمْ وَلَا جُلُودُكُمْ وَلَٰكِن ظَنَنتُمْ أَنَّ اللَّهَ لَا يَعْلَمُ كَثِيرًا مِّمَّا تَعْمَلُونَ‘‘ — اور تم اس بات سے چھپتے نہ تھے کہ تمہارے کان تمہاری آنکھیں اور تمہاری کھالیں تم پر گواہی دیں گی — بلکہ تم نے سمجھا کہ اللہ تمہارے اکثر اعمال نہیں جانتا — یعنی اور تم اس بات سے چھپتے نہ تھے کہ تمہارے کان تمہاری آنکھیں اور تمہاری کھالیں تم پر گواہی دیں گی بلکہ تم نے سمجھا کہ اللہ تمہارے اکثر اعمال نہیں جانتا۔
۳۔ عملی سبق: ظاہری پردہ کافی نہیں؛ دل کے معاملے میں اللہ سے ڈرو۔"""
),
4241: (
"اور یہی وہ گمان ہے جو تم نے اپنے رب کے بارے میں کیا اس نے تمہیں ہلاک کر دیا — پس تم خسارہ اٹھانے والوں میں سے ہو گئے",
"""۱۔ گمان کا نتیجہ — ظنّكم باللہ؛ أرداكم؛ فأصبحتم من الخاسرین۔
۲۔ ’’وَذَٰلِكُمْ ظَنُّكُمُ الَّذِي ظَنَنتُم بِرَبِّكُمْ أَرْدَاكُمْ فَأَصْبَحْتُم مِّنَ الْخَاسِرِينَ‘‘ — اور یہی وہ گمان ہے جو تم نے اپنے رب کے بارے میں کیا اس نے تمہیں ہلاک کر دیا — پس تم خسارہ اٹھانے والوں میں سے ہو گئے — یعنی اور یہی وہ گمان ہے جو تم نے اپنے رب کے بارے میں کیا اس نے تمہیں ہلاک کر دیا پس تم خسارہ اٹھانے والوں میں سے ہو گئے۔
۳۔ عملی سبق: اللہ کے بارے میں اچھا گمان رکھو؛ اللہ سے ڈرو۔"""
),
4242: (
"پھر اگر وہ صبر کریں تو آگ ان کا ٹھکانہ ہے — اور اگر وہ معافی مانگیں تو ان کی معافی قبول نہ کی جائے",
"""۱۔ انجام — فإن یصبروا فالنار مثوی لهم؛ و إن یستعتبوا فما هم من المعتبین۔
۲۔ ’’فَإِن يَصْبِرُوا فَالنَّارُ مَثْوًى لَّهُمْ وَإِن يَسْتَعْتِبُوا فَمَا هُم مِّنَ الْمُعْتَبِينَ‘‘ — پھر اگر وہ صبر کریں تو آگ ان کا ٹھکانہ ہے — اور اگر وہ معافی مانگیں تو ان کی معافی قبول نہ کی جائے — یعنی پھر اگر وہ صبر کریں تو آگ ان کا ٹھکانہ ہے اور اگر وہ معافی مانگیں تو ان کی معافی قبول نہ کی جائے۔
۳۔ عملی سبق: آج معافی مانگو؛ اللہ سے ڈرو۔"""
),
}
